  'base-render.components-date-range-style-calendar.c017': "   判的是**本件自己的内宽**（容器查询），不是视口宽。 */",
  /* ── packages/base-render/src/components/date-range/style.ts（#1226 迁入） ── */
  'base-render.components-date-range-style.c001': "/* date-range（日期范围 · 形态 B「日历缩略」）：起止两格 ＋ 一排快捷档（命中的带 ✓）＋ 一个月的格子，",
  'base-render.components-date-range-style.c002': "   底下那句口径点名「当前按 哪一档、从哪天到哪天、共几天」。零阴影下层次靠发丝线与底色块。 */",
  'base-render.components-date-range-style.c003': "/* 第一行：名字 ＋ 状态字（`当前按 本周`／`自定义区间`／`还未选`／`更新中`）。 */",
  'base-render.components-date-range-style.c004': '/* 状态字：一枚带发丝线的签（**字**这一档：换皮换不掉"按的是哪一档"）。 */',
  'base-render.components-date-range-style.c005': "/* 起止两格：两列（窄容器竖排），与快捷档／日历之间各留 {p0}px。 */",
  'base-render.components-date-range-style.c006': "/* 快捷档那一排：命中的一枚带 ✓ ＋ 走**强调面**（软底 `accent-soft` ＋ 主色字 `accent-text`",
  'base-render.components-date-range-style.c007': "   ＋ 主色描边 `accent`）＋ 加粗（**形 ＋ 字 ＋ 色**三样一起给）。口径住",
  'base-render.components-date-range-style.c008': '   `docs/base/base-render/选中态与皮肤语言.md` 第三节：有文字的选中面不许写成"实心反白"。 */',
  'base-render.components-date-range-style.c009': "/* ✓ 一直在标记里，只有按下的那一枚看得见——运行时段只管翻 `aria-pressed`，不用动标记。 */",
  'base-render.components-date-range-style.c010': "/* 悬停：只包在设备能力查询里（`hover:hover`），且**不是唯一通路**。",
  'base-render.components-date-range-style.c011': "   提示只给**不是两端**的格子：那两格是选中面（软底 ＋ 主色字 ＋ 主色描边），",
  'base-render.components-date-range-style.c012': "   若悬停时把底换成 `surface`、描边换成 `ink-2`，选中态在悬停那一刻就散了。 */",
  'base-render.components-date-range-style.c013': "/* 真按下：只动 `transform`（80ms 内看得见）。 */",
  'base-render.components-date-range-style.c014': "/* 可见焦点：翻月键、快捷档、日格、起止两格都 ≥2px 描边。 */",
  'base-render.components-date-range-style.c015': "/* 更新中：读数与格子保持原样（宽度锁住），状态字换成「更新中」；光标给 `progress`。 */",
  'base-render.components-date-range-style.c016': "/* 禁用：说不出为什么不能改是不许留的中间档（渲染期就要求给 `disabledReason`）。 */",
  'base-render.components-date-range-style.c017': "/* 错误说明：写在控件旁边（控件 `aria-describedby` 指向它），**不只染色**。 */",
  'base-render.components-date-range-style.c018': "/* 一句口径：`本周：09-19 到 09-25，共 7 天（含首尾）`（**要读的正文**，走 ink-2）。",
  'base-render.components-date-range-style.c019': "   调用方补的那句挂在后头，段间一条发丝线。 */",
  'base-render.components-date-range-style.c020': "/* 窄容器（<{p0}px）：起止两格竖排——一格一行，日期串读得全（不压字）。",
