  /* ── packages/base-render/src/components/multi-checks/style.ts（#1226 迁入） ── */
  'base-render.components-multi-checks-style.c001': "/* multi-checks（多选清单 · 形态 A「顶上全选 ＋ 分组复选 ＋ 底下动作」）：批量改之前先挑。",
  'base-render.components-multi-checks-style.c002': "   层次不靠阴影与大圆角（小票纸零阴影、大字报刊零圆角）：靠发丝线、字重与尺度差 ⇒ 换皮只换取值。 */",
  'base-render.components-multi-checks-style.c003': '/* 盒子自带纸面（不必外挂纸面页框）：边界清楚，否则"清单到哪儿为止"看不出来。 */',
  'base-render.components-multi-checks-style.c004': "/* 顶上那句「这清单是干什么的」：主字 ＋ 次段，都能换行（**不许 `…` 截断**）。 */",
  'base-render.components-multi-checks-style.c005': "/* 全选头：一枚总开关 ＋ 已选数。发丝线把它与清单分开。 */",
  'base-render.components-multi-checks-style.c006': "/* 已选数：等宽数字（数位一变宽就不跳版）。**不写 `nowrap`**：溢出比换行更难看。 */",
  'base-render.components-multi-checks-style.c007': "/* 勾选框：方盒（未勾）→ 方盒＋对钩（勾上）。盒与钩是**形状**，不靠色。 */",
  'base-render.components-multi-checks-style.c008': "/* 真状态永远住在原生框上：勾上／半勾的显形都从 `:checked` 与 `:indeterminate` 出发。 */",
  'base-render.components-multi-checks-style.c009': "/* 对钩（第二重：字）；半勾用一道横杠（形状分得出「勾了一部分」与「全勾」）。 */",
  'base-render.components-multi-checks-style.c010': "/* 原生框：视觉隐藏但**仍在无障碍树里**（1px 盒 ＋ `opacity:0`，不是 `display:none`）。 */",
  'base-render.components-multi-checks-style.c011': "/* 逐条那一列：分组之间一条发丝线。 */",
  'base-render.components-multi-checks-style.c012': "/* 分组头：整块是命中区（勾上＝这一组全勾）；底色与行分开，一眼看出哪几行是一组。 */",
  'base-render.components-multi-checks-style.c013': "/* 一行：勾选框 ＋ 主字（带副语）＋ 右端金额。整行是命中区（≥48px）。 */",
  'base-render.components-multi-checks-style.c014': "/* 副语与禁用原因：各占一行小字（不给就不出，不留空位）。 */",
  'base-render.components-multi-checks-style.c015': "/* 金额：右端等宽数字。**不写 `nowrap`**：金额长到装不下时宁可换行，也不横着溢出。 */",
  'base-render.components-multi-checks-style.c016': "/* 勾中的行：第一重（形状）＝左端竖条；第三重（颜色）＝软底。 */",
  'base-render.components-multi-checks-style.c017': "/* 鼠标悬停只是**提示**，不是唯一通路（勾选与焦点各有自己的标记）。 */",
  'base-render.components-multi-checks-style.c018': "/* 焦点：原生框收到键盘焦点时，整行／整块显形（**可见焦点，≥2px**）。 */",
  'base-render.components-multi-checks-style.c019': "/* 底下那一排：合计 ＋ 动作按钮（按钮在**下面**，正是本形态的样子）。 */",
  'base-render.components-multi-checks-style.c020': "/* 主按钮：强调底 ＋ 强调底上的字（`accent-ink` 是**强调底上的字色**那一档）。",
  'base-render.components-multi-checks-style.c021': "   挂在 `data-*` 标记上（不挂 `is-primary` 这类修饰类：短类名会与别件撞名）。 */",
  'base-render.components-multi-checks-style.c022': "/* 真按下：缩一格（≤80ms 内回弹；只动 transform，不触发布局）。 */",
  'base-render.components-multi-checks-style.c023': '/* 按不动：`cursor: not-allowed` ＋ 把"为什么"指给底下那句读数（`aria-describedby`）。 */',
  'base-render.components-multi-checks-style.c024': "/* 禁用与加载：行点不动（原因那句由标记渲染在行里）。判禁用走**原生** `:has(input[disabled])`；",
  'base-render.components-multi-checks-style.c025': "   判加载走根上的 `data-*`——状态只有一处事实，不另挂修饰类。 */",
  'base-render.components-multi-checks-style.c026': "/* 空态与加载态那一句：弱文字 ＋ 设计过的内距（不是留白）。 */",
  'base-render.components-multi-checks-style.c027': "/* 错态：写在控件旁边（不是只染色），并带一枚记号字。 */",
  'base-render.components-multi-checks-style.c028': "/* 窄容器（<{p0}px）：金额另起一行、左对齐（不再与主字抢那一行）。",
  'base-render.components-multi-checks-style.c029': "   判的是**本件自己的宽度**：本件会被嵌进侧栏／面板／卡片，视口宽 ≠ 组件宽（所以这里不用 `@media`）。 */",
  'base-render.components-multi-checks-style.c030': "/* 动效偏好：只关过渡，不关状态（状态不许卡在半路 ⇒ 不用 `transitionend` 驱动任何东西）。 */",
